{"implementation":"def solve(case):
    segments = case["segments"]
    allocations = [segment["minimum"] for segment in segments]
    remaining = case["budget"] - sum(allocations)
    order = sorted(range(len(segments)), key=lambda i: (-segments[i]["importance"], i))
    for i in order:
        if remaining <= 0:
            break
        extra = min(segments[i]["capacity"] - allocations[i], remaining)
        allocations[i] += extra
        remaining -= extra
    return {
        "allocations": allocations,
        "by_name": {segment["name"]: allocations[i] for i, segment in enumerate(segments)},
        "total": sum(allocations)
    }"}
